import picker from '@ohos.file.picker';
import fs from '@ohos.file.fs';
import { BusinessError } from '@ohos.base';
import ble from '@ohos.bluetooth.ble';
import { util, buffer } from '@kit.ArkTS';
import { MinizipNative } from '@ohos/minizip'
import { DfuServiceInitiator, DfuServiceController,
  DfuServiceListenerHelper, DfuProgressListener } from 'ohos_dfu_library'
import hilog from '@ohos.hilog';
import { BleModel } from '../model/BleModel';
import { constant } from '@kit.ConnectivityKit';
import { promptAction } from '@kit.ArkUI'

interface Manifest {
  'application': FileInfo,
  'bootloader': FileInfo,
  'softdevice': FileInfo,
}

interface FileInfo {
  'bin_file': string,
  'dat_file': string,
}

interface ManifestFile {
  'manifest': Manifest,
}

class ProgressListener implements DfuProgressListener {
  public bootloaderCB: (deviceAddress: string)=>void = (deviceAddress: string)=>{};
  public dfuInitializedCB: ()=>void = ()=>{};
  public completeCB: ()=>void = ()=>{};
  public uploadingCB: (percent: number) => void = (percent: number) => {};
  public deviceConnectingCB: (deviceAddress: string) => void = (deviceAddress: string) => {};
  public dfuProcessStartingCB: (deviceAddress: string) => void = (deviceAddress: string) => {};
  public enablingDfuModeCB: (deviceAddress: string) => void = (deviceAddress: string) => {};
  public deviceConnectedCB: (deviceAddress: string) => void = (deviceAddress: string) => {};
  public dfuProcessStartedCB: (deviceAddress: string) => void = (deviceAddress: string) => {};
  public progressChangedCB: (deviceAddress: string) => void = (deviceAddress: string) => {};
  public deviceDisconnectingCB: (deviceAddress: string) => void = (deviceAddress: string) => {};
  public dfuProcessStarted: (deviceAddress: string) => void = (deviceAddress: string) => {};
  public firmwareValidatingCB: (deviceAddress: string) => void = (deviceAddress: string) => {};
  public dfuAbortedCB: (deviceAddress: string) => void = (deviceAddress: string) => {};
  public errorCB: (deviceAddress: string, error: number, errorType: number, message: string) => void =
    (deviceAddress: string, error: number, errorType: number, message: string) => {};
  dispose(): void {
  }
  onDeviceConnecting(deviceAddress: string): void {
    hilog.info(DOMAIN, TAG, `onDeviceConnecting`);
    this.deviceConnectingCB(deviceAddress);
  }
  onDfuProcessStarting(deviceAddress: string): void {
    hilog.info(DOMAIN, TAG, `onDfuProcessStarting`);
    this.dfuInitializedCB();
  }
  onEnablingDfuMode(deviceAddress: string): void {
    hilog.info(DOMAIN, TAG, `onEnablingDfuMode`);
    this.bootloaderCB(deviceAddress);
  }
  onDeviceConnected(deviceAddress: string): void {
    hilog.info(DOMAIN, TAG, `onDeviceConnected`);
    this.deviceConnectedCB(deviceAddress);
  }
  onDfuProcessStarted(deviceAddress: string): void {
    hilog.info(DOMAIN, TAG, `onDfuProcessStarted`);
    this.dfuProcessStartedCB(deviceAddress);
  }
  onProgressChanged(deviceAddress: string, percent: number, speed: number,
    avgSpeed: number, currentPart: number, partsTotal: number): void {
    hilog.info(DOMAIN, TAG, `onProgressChanged`);
    this.uploadingCB(percent);
  }
  onFirmwareValidating(deviceAddress: string): void {
    hilog.info(DOMAIN, TAG, `onFirmwareValidating`);
    this.firmwareValidatingCB(deviceAddress);
  }
  onDeviceDisconnecting(deviceAddress: string): void {
    hilog.info(DOMAIN, TAG, `onDeviceDisconnecting`);
    this.deviceConnectingCB(deviceAddress);
  }
  onDeviceDisconnected(deviceAddress: string): void {
    hilog.info(DOMAIN, TAG, `onDeviceDisconnected`);
    this.deviceConnectedCB(deviceAddress);
  }
  onDfuCompleted(deviceAddress: string): void {
    hilog.info(DOMAIN, TAG, `onDfuCompleted`);
    this.completeCB();
  }
  onDfuAborted(deviceAddress: string): void {
    hilog.info(DOMAIN, TAG, `onDfuAborted`);
    this.dfuAbortedCB(deviceAddress);
  }
  onError(deviceAddress: string, error: number, errorType: number, message: string): void {
    hilog.info(DOMAIN, TAG, `onError`);
    this.errorCB(deviceAddress, error, errorType, message);
  }
}

const DOMAIN = 0x8691;
const TAG = 'ohdfu';

const GIANT_OTA = 'PLANET'
const MULAN_OTA = 'MD2-HA'

@Entry
@Component
struct Index {
  @State message: Resource = $r('app.string.title_label');
  @State selectFile: Resource = $r('app.string.select_file_label');
  @State selectDevice: Resource = $r('app.string.select_device_label');
  @State bootloaderMsg: Resource = $r('app.string.boot_loader_msg_label', '');
  @State dfuInitialized: Resource = $r('app.string.dfu_initial_msg_label', '');
  @State uploadingMsg: Resource = $r('app.string.upload_msg_label', '');
  @State completeMsg: Resource = $r('app.string.complete_msg_label', '');
  @State controlMsg: Resource = $r('app.string.start_button');
  @State fileName: string = '...';
  @State fileSize: string = '...';
  @State deviceName: string = '...';
  @State deviceMac: string = '...';
  @State otaDeviceName: string = '...';
  @State otaDeviceMac: string = '...';
  // @State filterValue: string = 'MD2-HA'
  @State filterValue: string = MULAN_OTA
  @State filterIndex: number = 0;
  @State otaFilterValue: string = 'OTA'
  @State canControl: boolean = true;
  @State canFindDevice: boolean = true;
  private gattClient: ble.GattClientDevice | undefined = undefined;
  private presolve: ((value: string | PromiseLike<string>) => void) | null = null;
  private gatt: ble.GattClientDevice | null = null;
  private selectGc: ble.BLECharacteristic | null = null;
  private dfuContorller: DfuServiceController | null = null;
  private controlFlag: string = 'start';

  bootloaderCB: ()=>void = () => {
    this.bootloaderMsg = $r('app.string.boot_loader_msg_label', ' Done!');
  }

  dfuInitializedCB: ()=>void = () => {
    this.dfuInitialized = $r('app.string.dfu_initial_msg_label', ' Done!');
    this.controlMsg = $r('app.string.abort_button');
    this.controlFlag = 'abort';
    hilog.info(DOMAIN, TAG, `DfuServiceInitiator change2abort`);
    this.canControl = true;
  }

  uploadingCB: (percent: number)=>void = (percent: number) => {
    this.uploadingMsg = $r('app.string.upload_msg_label', percent.toFixed(2)+'%');
    if (percent == 100) {
      this.completeMsg = $r('app.string.complete_msg_label', ' Done!');
      this.controlMsg = $r('app.string.start_button');
      this.controlFlag = 'start';
      hilog.info(DOMAIN, TAG, `DfuServiceInitiator change2start`);
      this.canControl = true;
    }
  }

  abortCB: (address: string)=>void = (address: string) => {
    this.controlMsg = $r('app.string.start_button');
    this.controlFlag = 'start';
    hilog.info(DOMAIN, TAG, `DfuServiceInitiator change2abort`);
    this.canControl = true;
  }

  completeCB: ()=>void = () => {
    this.completeMsg = $r('app.string.complete_msg_label', 'Done!');
  }

  onPageShow(): void {

  }

  unzip(fpath: string) {
    let minizipEntry = new MinizipNative(fpath);
    let ret = minizipEntry.Open();
    if (ret == 0) {
      let entryNames = minizipEntry.GetEntryNames();
      for (let i = 0; i < entryNames.length; i++) {
        if(!entryNames[i].endsWith("/")) {
          let arrBuffer = minizipEntry.ExtractFileToJS(entryNames[i], '');
          if (arrBuffer) {
            let ubuf = new Uint8Array(arrBuffer);
            hilog.info(DOMAIN, TAG, `Minizip ${entryNames[i]}: ${ubuf.byteLength}, ${ubuf[0].toString(16)}, ${ubuf[1].toString(16)}, ${ubuf[2].toString(16)}`)
          }
          if (entryNames[i] == 'manifest.json') {
            let decoder = util.TextDecoder.create('utf-8');
            let str = decoder.decodeToString(new Uint8Array(arrBuffer));
            const manbj: ManifestFile = JSON.parse(str);
            // {"manifest":{"application":{"bin_file":"nrf52832_HA_App.bin","dat_file":"nrf52832_HA_App.dat"}}}
            if (manbj.manifest.application) {
              hilog.info(DOMAIN, TAG, `Manifest application: ${JSON.stringify(manbj.manifest.application)}`);
            }
            if (manbj.manifest.bootloader) {
              hilog.info(DOMAIN, TAG, `Manifest bootloader: ${JSON.stringify(manbj.manifest.bootloader)}`);
            }
            if (manbj.manifest.softdevice) {
              hilog.info(DOMAIN, TAG, `Manifest softdevice: ${JSON.stringify(manbj.manifest.softdevice)}`);
            }
          }
        }
      }
    } else {
      console.info(`minizipEntry: ${ret}`);
    }
  }

  async runDfu(mac: string) {
    let starter: DfuServiceInitiator = new DfuServiceInitiator(mac);
    hilog.info(DOMAIN, TAG, `DfuServiceInitiator`);
    starter.setZipUri(this.fileName);

    let progressListener: ProgressListener = new ProgressListener();
    progressListener.bootloaderCB = this.bootloaderCB;
    progressListener.dfuInitializedCB = this.dfuInitializedCB;
    progressListener.uploadingCB = this.uploadingCB;
    progressListener.completeCB = this.completeCB;
    progressListener.dfuAbortedCB = this.abortCB;
    progressListener.deviceConnectedCB = this.abortCB;
    DfuServiceListenerHelper.registerProgressListener(progressListener);
    this.dfuContorller = starter.start();
  }

  async startGiantOta(): Promise<boolean> {
    if (this.deviceName.includes(GIANT_OTA)) {
      try {
        let that = this;
        ble.on("BLEDeviceFind", (data: Array<ble.ScanResult>) => {
          for (const item of data) {
            if (item.deviceName.includes(this.otaFilterValue)) {
              console.info(`scanres: ${item.deviceName},${item.deviceId}`);
              ble.off("BLEDeviceFind");
              ble.stopBLEScan();
              that.otaDeviceName = item.deviceName;
              that.otaDeviceMac = item.deviceId;
              that.runDfu(that.otaDeviceMac);
            } else {
              console.info(`scanres: ${item.deviceName},${item.deviceId}`);
            }
          }
        });

        let scanFilter: ble.ScanFilter = {};
        // let scanFilter: ble.ScanFilter = {name:'MD2-HA20-F220231200085'};
        // let scanFilter: ble.ScanFilter = {
        //   deviceId:"XX:XX:XX:XX:XX:XX",
        //   name:"test",
        //   serviceUuid:"00001888-0000-1000-8000-00805f9b34fb"
        // };
        let scanOptions: ble.ScanOptions = {
          interval: 500,
          dutyMode: ble.ScanDuty.SCAN_MODE_LOW_POWER,
          matchMode: ble.MatchMode.MATCH_MODE_AGGRESSIVE,
        }
        ble.startBLEScan([scanFilter],scanOptions);
      } catch (err) {
        hilog.error(DOMAIN, TAG, 'errCode: ' + (err as BusinessError).code + ', errMessage: ' + (err as BusinessError).message);
      }
      return true;
    }
    return false;
  }

  async isGiantOta() {
    if (this.deviceName.includes(GIANT_OTA)) {
      await this.connect(this.deviceMac);
      await this.writeCharacter();
      this.gattClient?.disconnect();
    }
  }

  async connect(deviceId: string): Promise<void> {
    try {
      let tresolve: ((value: void | PromiseLike<void>) => void) | null = null;
      let gattClient: ble.GattClientDevice = ble.createGattClientDevice(deviceId);
      this.gattClient = gattClient;
      BleModel.gattClient = gattClient;
      gattClient.on("BLEConnectionStateChange", (cs: ble.BLEConnectionChangeState) => {
        hilog.info(DOMAIN, TAG, `BLEConnectionStateChange: ${JSON.stringify(cs)}`);
        switch (cs.state) {
          case constant.ProfileConnectionState.STATE_CONNECTED:
            {
              this.gatt = gattClient;
              if (tresolve) {
                tresolve();
              }
            }
            break;
          case constant.ProfileConnectionState.STATE_DISCONNECTED:
            {
              gattClient.off("BLEConnectionStateChange");
            }
            break;
          default:
            break;
        }
      })
      return new Promise<void>((resovle) => {
        gattClient.connect();
        tresolve = resovle;
      })
    } catch(e) {
      hilog.error(DOMAIN, TAG, `connect err: ${JSON.stringify(e)}`);
    }
  }

  // this is for gaint to enter in OTA mode
  async writeCharacter(): Promise<void> {
    let tresolve: ((value: void | PromiseLike<void>) => void) | null = null;
    let gsList: Array<ble.GattService>|undefined = await this.gatt?.getServices();

    if (gsList) {
      for (const gsitem of gsList) {
        hilog.info(DOMAIN, TAG, `readService: ${JSON.stringify(gsitem)}`);
        if (gsitem.serviceUuid.includes('FD00')) {
          for (const gcitem of gsitem.characteristics) {
            if (gcitem.characteristicUuid.includes('FD0A')) {
              hilog.info(DOMAIN, TAG, `Find Characteristic: ${JSON.stringify(gcitem)}`);
              this.selectGc = gcitem;
              break;
            }
          }
        }
      }
    }
    let init: number[] = [0xA2,0x04,0x01,0xA7];
    let u8array: Uint8Array = new Uint8Array(init)

    if (this.selectGc) {
      let ncha: ble.BLECharacteristic = {
        serviceUuid: this.selectGc.serviceUuid,
        characteristicUuid: this.selectGc.characteristicUuid,
        characteristicValue: u8array.buffer,
        descriptors: this.selectGc.descriptors,
        properties: this.selectGc.properties,
      }
      this.selectGc = ncha;
      hilog.info(DOMAIN, TAG, `Write characteristicValue： ${JSON.stringify(ncha)}`);
      if (this.gatt) {
        this.gatt.on("BLECharacteristicChange", (cdata: ble.BLECharacteristic) => {
          hilog.info(DOMAIN, TAG, `BLECharacteristicChange: ${JSON.stringify(cdata)}`);
          this.gatt?.off("BLECharacteristicChange");
        })
        this.gatt?.on("BLEConnectionStateChange", (sta: ble.BLEConnectionChangeState) => {
          hilog.info(DOMAIN, TAG, `BLEConnectionStateChange: ${JSON.stringify(sta)}`);
          this.gatt?.off("BLEConnectionStateChange");
        })
        await this.gatt?.writeCharacteristicValue(ncha, ble.GattWriteType.WRITE);
      }
    }

    return;
  }

  build() {
    RelativeContainer() {
      Column() {
        Text(this.message)
          .id('DFU Test')
          .fontSize(20)
          .fontWeight(FontWeight.Bold)
          .width('100%')
          .height('10%')
          .alignRules({
            center: { anchor: '__container__', align: VerticalAlign.Center },
            middle: { anchor: '__container__', align: HorizontalAlign.Center }
          })
        Column() {
          Column() {
            Row() {
              Text(this.selectFile)
                .width('70%')
              Button($r('app.string.file_button'))
                .width('30%')
                .onClick(() => {
                  try {
                    let documentSelectOptions = new picker.DocumentSelectOptions();
                    let documentPicker = new picker.DocumentViewPicker();
                    let that = this;
                    documentPicker.select(documentSelectOptions).then(async (documentSelectResult: Array<string>) => {
                      hilog.info(DOMAIN, TAG, 'DocumentViewPicker.select successfully, documentSelectResult uri: ' + JSON.stringify(documentSelectResult));
                      that.fileName = documentSelectResult[0]
                      let file = fs.openSync(that.fileName, fs.OpenMode.READ_ONLY);
                      hilog.info(DOMAIN, TAG, `openReadSync: get fd success. file ${JSON.stringify(file)}`)
                      hilog.info(DOMAIN, TAG, `openReadSync: get fd success. fd ${JSON.stringify(file.fd)}`)
                      let sta = fs.statSync(file.fd);
                      hilog.info(DOMAIN, TAG, `fstate: ${JSON.stringify(sta)},${sta.size},${sta.ctime}`);
                      that.fileSize = sta.size.toString();
                      that.unzip(file.path);
                      fs.closeSync(file.fd);
                    }).catch((err: BusinessError) => {
                      hilog.error(DOMAIN, TAG, 'DocumentViewPicker.select failed with err: ' + JSON.stringify(err));
                    });
                  } catch (error) {
                    let err: BusinessError = error as BusinessError;
                    hilog.error(DOMAIN, TAG, 'DocumentViewPicker failed with err: ' + JSON.stringify(err));
                  }
                })
            }
            .padding(20)
            Row() {
              Text($r('app.string.path_label'))
                .width('20%')
              Text(this.fileName)
                .width('70%')
            }
            Row() {
              Text($r('app.string.size_label'))
                .width('20%')
              Text(this.fileSize)
                .width('70%')
            }

          }
          .backgroundColor('#ffffff')
          .borderWidth(1)
          .borderRadius(10)
          .borderColor('#ffefef')
          .padding({bottom:20})

          Column(){
            Row() {
              Text(this.selectDevice)
                .width('30%')
              Select([{ value: MULAN_OTA }, { value: GIANT_OTA }])
                .value(this.filterValue)
                .backgroundColor(Color.White)
                .borderRadius(19)
                .constraintSize({ minWidth: 100 })
                .selected(this.filterIndex)
                .onSelect((index, value) => {
                  this.filterIndex = index;
                  this.filterValue = value;
                })
                .height(50)
                .width('40%')
                .borderRadius(2)
              Button($r('app.string.device_button'))
                .enabled(this.canFindDevice)
                .width('30%')
                .onClick(() => {
                  try {
                    let that = this;
                    this.canFindDevice = false;
                    setTimeout(() => {
                      hilog.info(DOMAIN, TAG, 'delay 30s');
                      if (this.canFindDevice == false) {
                        promptAction.showToast({
                          message: '超时（30秒）未找到设备',
                          duration: 2000
                        });
                        ble.off("BLEDeviceFind");
                        ble.stopBLEScan();
                        this.canFindDevice = true;
                      }
                    }, 30000);
                    ble.on("BLEDeviceFind", (data: Array<ble.ScanResult>) => {
                      for (const item of data) {
                        if (item.deviceName.includes(this.filterValue)) {
                          hilog.info(DOMAIN, TAG, `scanres: ${item.deviceName},${item.deviceId}`);
                          ble.off("BLEDeviceFind");
                          ble.stopBLEScan();
                          that.deviceName = item.deviceName;
                          that.deviceMac = item.deviceId;
                          this.canFindDevice = true;
                          // that.blemsg = that.selectDevName;
                          that.isGiantOta();
                        } else {
                          hilog.info(DOMAIN, TAG, `scanres: ${item.deviceName},${item.deviceId}`);
                        }
                      }
                    });

                    let scanFilter: ble.ScanFilter = {};
                    // let scanFilter: ble.ScanFilter = {name:'MD2-HA20-F220231200085'};
                    // let scanFilter: ble.ScanFilter = {
                    //   deviceId:"XX:XX:XX:XX:XX:XX",
                    //   name:"test",
                    //   serviceUuid:"00001888-0000-1000-8000-00805f9b34fb"
                    // };
                    let scanOptions: ble.ScanOptions = {
                      interval: 500,
                      dutyMode: ble.ScanDuty.SCAN_MODE_LOW_POWER,
                      matchMode: ble.MatchMode.MATCH_MODE_AGGRESSIVE,
                    }
                    ble.startBLEScan([scanFilter],scanOptions);
                  } catch (err) {
                    hilog.error(DOMAIN, TAG, 'errCode: ' + (err as BusinessError).code + ', errMessage: ' + (err as BusinessError).message);
                  }
                })
            }
            .padding(20)
            Row() {
              Text($r('app.string.name_label'))
                .width('20%')
              Text(this.deviceName)
                .width('70%')
            }
            Row() {
              Text($r('app.string.addr_label'))
                .width('20%')
              Text(this.deviceMac)
                .width('70%')
            }

          }
          .backgroundColor('#ffffff')
          .borderWidth(1)
          .borderRadius(10)
          .borderColor('#ffefef')
          .padding({bottom:20})


          Column() {
            Row() {
              Text($r('app.string.progress_label'))
                .width('70%')
              Button(this.controlMsg)
                .width('30%')
                .enabled(this.canControl)
                .onClick(async () => {
                  this.canControl = false;
                  setTimeout(() => {
                    hilog.info(DOMAIN, TAG, 'delay 30s');
                    if (this.canControl == false) {
                      promptAction.showToast({
                        message: '超时（30秒）未开始，请检查升级设备',
                        duration: 2000
                      });
                      this.canControl = true;
                    }
                  }, 30000);
                  if (this.controlFlag == 'start') {
                    if ((await this.startGiantOta())) {
                      return;
                    } else {
                      this.runDfu(this.deviceMac);
                    }
                  } else {
                    this.dfuContorller?.abort();
                    hilog.error(DOMAIN, TAG, 'dfuaction');
                  }
                })
            }
            .padding(5)
            Text(this.bootloaderMsg)
              .width('100%')
              .padding({left:10,bottom:5})
            Text(this.dfuInitialized)
              .width('100%')
              .padding({left:10,bottom:5})
            Text(this.uploadingMsg)
              .width('100%')
              .padding({left:10,bottom:5})
            // if (this.uploadingValue > 0) {
            //   Progress({value: this.uploadingValue, total: 100, type:ProgressType.Linear})
            //     .style({strokeWidth: 10, enableSmoothEffect: true})
            // }
            Text(this.completeMsg)
              .width('100%')
              .padding({left:10})
          }
          .backgroundColor('#ffffff')
          .padding(20)
          .borderRadius(10)
        }
        .width('100%')
        .borderRadius(5)
      }
      .height('98%')
      .width('100%')
      .padding({left:10,right:10})
      .backgroundColor('#eeffff')

    }
    .height('100%')
    .width('100%')
  }
}
